<script lang="ts">let {form}= $props();</script>
<div class="hii-page max-w-3xl"><header class="hii-page-header"><p class="hii-kicker">HII exchange</p><h1 class="hii-page-title">New exchange</h1><p class="hii-page-copy">A file, terms, and a price become one shareable link.</p></header>
{#if form?.linkUrl}<div class="hii-card mt-6 bg-[var(--hii-soft-green)]"><p class="text-emerald-700">Exchange created. Share this link:</p><a href={form.linkUrl} class="mt-2 block break-all font-mono text-sm underline">{form.linkUrl}</a></div>{/if}
<form method="POST" enctype="multipart/form-data" class="hii-card mt-6 space-y-4"><label class="block"><span class="text-sm text-neutral-600">Title</span><input name="title" required class="hii-field mt-1 w-full px-3 py-2"/></label><label class="block"><span class="text-sm text-neutral-600">Description (optional)</span><textarea name="description" rows="2" class="hii-textarea mt-1 w-full px-3 py-2"></textarea></label><label class="block"><span class="text-sm text-neutral-600">Price (USD)</span><input name="price" type="number" min="0" step="0.01" value="9.99" required class="hii-field mt-1 w-full px-3 py-2"/></label><fieldset class="border border-[rgba(23,107,255,.24)] p-4"><legend>Terms</legend><input name="license_name" value="Standard" class="hii-field mt-1 w-full px-3 py-2" aria-label="License name"/><select name="exclusivity" class="hii-select mt-3 w-full px-3 py-2"><option value="non-exclusive">Non-exclusive</option><option value="exclusive">Exclusive</option><option value="lease">Lease</option></select><textarea name="terms" rows="2" class="hii-textarea mt-3 w-full px-3 py-2" placeholder="What the buyer is allowed to do with this."></textarea></fieldset><label class="block"><span class="text-sm text-neutral-600">File</span><input name="file" type="file" required class="mt-1 block w-full text-sm"/></label>{#if form?.error}<p class="text-red-600">{form.error}</p>{/if}<button class="hii-command-button">Create exchange link</button></form></div>
